1.2 Fin Planform Geometries
Fin shape—or planform—directly impacts aerodynamic performance, structural behavior, and manufacturing complexity. The most common planforms used in rocketry are summarized below.

1.2.1 Taxonomy









Geometry
Key Parameters
Taper Ratio (\(\lambda\))
Character




Rectangular
\(C_r\), \(s\)
\(\lambda = 1\)
Simple to build. Higher drag at transonic speeds


Delta
\(C_r\), \(s\), \(\ell_m\)
\(\lambda = 0\)
Low drag, structurally stiff. Common in HPR


Clipped Delta
\(C_r\), \(C_t\), \(s\), \(\ell_m\)
\(0 &lt; \lambda &lt; 1\)
Good all-around compromise — most popular for HPR


Trapezoidal
\(C_r\), \(C_t\), \(s\), \(\ell_m\)
\(0 &lt; \lambda &lt; 1\)
General form; clipped delta is a special case


Elliptical
\(C_r\), \(s\)
N/A
Minimum induced drag (same principle as Spitfire wings)





1.2.2 Shape Comparison
Use the sliders below to see all five planforms drawn to the same scale.


Code
viewof comp_cr = Inputs.range([4, 20], {value: 10, step: 0.5, label: "Root Chord Cr [cm]"})
viewof comp_span = Inputs.range([3, 15], {value: 8, step: 0.5, label: "Span s [cm]"})


















Code
{
  // Derived parameters
  const cr = comp_cr;
  const s = comp_span;
  const ct_clipped = cr * 0.4;  // λ ≈ 0.4 for clipped delta
  const sweep_delta = cr * 0.7; // typical sweep for delta
  const sweep_clipped = cr * 0.5;

  const W = 700;
  const cellW = W / 5;
  const H = 180;
  const pad = 12;
  const scale = Math.min((cellW - 2 * pad) / cr, (H - 50) / s) * 0.85;

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${W} ${H + 10}`)
    .attr("width", "100%")
    .style("max-width", `${W}px`)
    .style("font-family", "'Inter', 'Segoe UI', system-ui, sans-serif");

  const fins = [
    {
      label: "Rectangular",
      points: [[0,0],[0,s],[cr,s],[cr,0]],
      color: "#3b82f6"
    },
    {
      label: "Delta",
      points: [[0,0],[sweep_delta, s],[cr,0]],
      color: "#8b5cf6"
    },
    {
      label: "Clipped Delta",
      points: [[0,0],[sweep_clipped, s],[sweep_clipped + ct_clipped, s],[cr,0]],
      color: "#06b6d4"
    },
    {
      label: "Trapezoidal",
      points: [[0,0],[cr*0.3, s],[cr*0.3 + cr*0.5, s],[cr,0]],
      color: "#f59e0b"
    },
    {
      label: "Elliptical",
      points: null, // handled separately
      color: "#ef4444"
    }
  ];

  fins.forEach((fin, i) =&gt; {
    const g = svg.append("g")
      .attr("transform", `translate(${i * cellW + cellW/2}, ${H - 15})`);

    if (fin.points) {
      // Polygon fins
      const pts = fin.points.map(([x,y]) =&gt;
        `${(x - cr/2) * scale},${-y * scale}`
      ).join(" ");

      g.append("polygon")
        .attr("points", pts)
        .attr("fill", fin.color)
        .attr("fill-opacity", 0.3)
        .attr("stroke", fin.color)
        .attr("stroke-width", 2);
    } else {
      // Elliptical fin
      const nPts = 60;
      const ellPts = [];
      for (let j = 0; j &lt;= nPts; j++) {
        const y = (j / nPts) * s;
        const chord = cr * Math.sqrt(1 - (y/s)*(y/s));
        ellPts.push([(chord/2) * scale, -y * scale]);   // right edge
      }
      // Mirror for full shape
      const fullPts = [];
      for (let j = 0; j &lt; ellPts.length; j++) {
        fullPts.push(ellPts[j]);
      }
      for (let j = ellPts.length - 1; j &gt;= 0; j--) {
        fullPts.push([-ellPts[j][0], ellPts[j][1]]);
      }
      const pathD = "M " + fullPts.map(p =&gt; p.join(",")).join(" L ") + " Z";

      g.append("path")
        .attr("d", pathD)
        .attr("fill", fin.color)
        .attr("fill-opacity", 0.3)
        .attr("stroke", fin.color)
        .attr("stroke-width", 2);
    }

    // Body tube line (root)
    g.append("line")
      .attr("x1", -cr/2 * scale - 5).attr("y1", 0)
      .attr("x2", cr/2 * scale + 5).attr("y2", 0)
      .attr("stroke", "#64748b")
      .attr("stroke-width", 1.5)
      .attr("stroke-dasharray", "4,3");

    // Label
    g.append("text")
      .attr("x", 0).attr("y", 16)
      .attr("text-anchor", "middle")
      .attr("fill", fin.color)
      .attr("font-size", 11)
      .attr("font-weight", "600")
      .text(fin.label);
  });

  return svg.node();
}













Note



The dashed line represents the body tube surface (fin root). All fins share the same root chord and span for direct comparison.

2.2 Geometry Definitions
A standard trapezoidal fin is defined by four geometric parameters:


Code
viewof root_chord = Inputs.range([1, 20], {value: 10, step: 0.1, label: "Root Chord (Cr) [cm]"})
viewof tip_chord = Inputs.range([0, 20], {value: 5, step: 0.1, label: "Tip Chord (Ct) [cm]"})
viewof span = Inputs.range([1, 20], {value: 8, step: 0.1, label: "Fin Span (s) [cm]"})
viewof sweep = Inputs.range([0, 20], {value: 4, step: 0.1, label: "Sweep Length (ℓm) [cm]"})






































Parameter
Symbol
Description




Root Chord
\(C_r\)
Length of the fin edge attached to the body tube


Tip Chord
\(C_t\)
Length of the fin at its outermost edge


Span
\(s\)
Radial distance from the body surface to the fin tip


Sweep Length
\(\ell_m\)
Longitudinal offset of the tip leading edge from the root leading edge


Taper Ratio
\(\lambda = C_t / C_r\)
Ratio of tip chord to root chord (0 = delta, 1 = rectangular)




2.2.1 Fin Shape Visualization
The blue shape below shows the fin planform. The red dot marks the aerodynamic center of pressure for this single fin (computed via the Barrowman formula in the next section).


Code
fin_area = (root_chord + tip_chord) / 2 * span
taper_ratio = tip_chord / root_chord

// Mid-chord line length (distance between midpoints of root and tip chords)
mid_chord_offset = sweep + tip_chord / 2 - root_chord / 2
l_mc = Math.sqrt(span * span + mid_chord_offset * mid_chord_offset)

// --- Center of Pressure (single fin, from root leading edge) ---
// Barrowman formula for CP of a trapezoidal fin
Xf = (sweep * (root_chord + 2 * tip_chord)) / (3 * (root_chord + tip_chord))
   + (1 / 6) * (root_chord + tip_chord - (root_chord * tip_chord) / (root_chord + tip_chord))

// Approximate CP spanwise position (at 1/3 span from root, standard approximation)
Yf_cp = span / 3














































Code
{
  const margin = 2;
  const xMax = Math.max(root_chord, sweep + tip_chord) + margin;
  const yMax = span + margin;

  return Plot.plot({
    aspectRatio: 1,
    width: 500,
    x: {label: "Length [cm]", domain: [0, xMax]},
    y: {label: "Span [cm]", domain: [0, yMax]},
    marks: [
      // Fin shape (filled polygon)
      Plot.line(
        [
          {x: 0, y: 0},
          {x: sweep, y: span},
          {x: sweep + tip_chord, y: span},
          {x: root_chord, y: 0},
          {x: 0, y: 0}
        ],
        {x: "x", y: "y", fill: "steelblue", fillOpacity: 0.4, stroke: "steelblue", strokeWidth: 2}
      ),
      // Dimension annotations — root chord
      Plot.text([{x: root_chord / 2, y: -0.6}], {text: d =&gt; `Cr = ${root_chord.toFixed(1)}`, fontSize: 11, fill: "#333"}),
      // Dimension annotations — tip chord
      Plot.text([{x: sweep + tip_chord / 2, y: span + 0.6}], {text: d =&gt; `Ct = ${tip_chord.toFixed(1)}`, fontSize: 11, fill: "#333"}),
      // Dimension annotations — span (vertical)
      Plot.text([{x: -0.8, y: span / 2}], {text: d =&gt; `s`, fontSize: 12, fill: "#555", fontWeight: "bold"}),
      // Sweep arrow annotation
      Plot.text([{x: sweep / 2, y: span + 1.0}], {text: d =&gt; `ℓm = ${sweep.toFixed(1)}`, fontSize: 10, fill: "#888"}),
      // Center of Pressure dot
      Plot.dot([{x: Xf, y: Yf_cp}], {fill: "red", r: 6, title: "Center of Pressure"}),
      Plot.text([{x: Xf + 1.2, y: Yf_cp}], {text: d =&gt; "CP", fill: "red", fontWeight: "bold", fontSize: 12})
    ]
  });
}

2.4 Full Rocket Stability Calculator
Use the controls below to define your full rocket geometry and compute the stability margin.

2.4.1 Rocket Parameters


Code
viewof body_diameter = Inputs.range([1, 20], {value: 4, step: 0.1, label: "Body Diameter (d) [cm]"})
viewof body_length = Inputs.range([10, 150], {value: 60, step: 1, label: "Body Length [cm]"})
viewof nose_length = Inputs.range([2, 40], {value: 12, step: 0.5, label: "Nose Cone Length (Ln) [cm]"})
viewof nose_type = Inputs.select(["Conical", "Ogive"], {value: "Ogive", label: "Nose Cone Type"})
viewof n_fins = Inputs.select([3, 4], {value: 4, label: "Number of Fins (N)"})
viewof fin_position = Inputs.range([10, 150], {value: 50, step: 0.5, label: "Nose Tip to Fin LE (X_fLE) [cm]"})
viewof cg_position = Inputs.range([5, 100], {value: 30, step: 0.5, label: "CG Position from Nose Tip [cm]"})





















































2.4.2 Computed Results


Code
CNa_nose = 2  // Barrowman: always 2 for any nose shape
Xcp_nose = nose_type === "Conical" ? 0.666 * nose_length : 0.466 * nose_length

// --- Fins ---
R_body = body_diameter / 2
Kfb = 1 + R_body / (span + R_body)

// Mid-chord line length
mid_chord_offset2 = sweep + tip_chord / 2 - root_chord / 2
l_mc2 = Math.sqrt(span * span + mid_chord_offset2 * mid_chord_offset2)

// CNα for the fin set (uncorrected)
CNa_fins_raw = (4 * n_fins * Math.pow(span / body_diameter, 2)) /
  (1 + Math.sqrt(1 + Math.pow(2 * l_mc2 / (root_chord + tip_chord), 2)))

// CNα for the fin set (corrected with interference factor)
CNa_fins = CNa_fins_raw * Kfb

// Fin CP from nose tip
Xcp_fins = fin_position + Xf

// --- Total Rocket ---
CNa_total = CNa_nose + CNa_fins
Xcp_total = (CNa_nose * Xcp_nose + CNa_fins * Xcp_fins) / CNa_total

// --- Stability ---
stability_margin = (Xcp_total - cg_position) / body_diameter

stability_status = stability_margin &gt;= 1.0 ? "✅ Stable" :
                   stability_margin &gt;= 0.5 ? "⚠️ Marginally Stable" :
                   "❌ Unstable"

stability_color = stability_margin &gt;= 1.0 ? "#22c55e" :
                  stability_margin &gt;= 0.5 ? "#eab308" :
                  "#ef4444"






































































































